from html.parser import HTMLParser
import sys,re
class P(HTMLParser):
 def __init__(self): super().__init__(); self.skip=0; self.out=[]
 def handle_starttag(self,t,a):
  if t in ('script','style','noscript'): self.skip+=1
 def handle_endtag(self,t):
  if t in ('script','style','noscript') and self.skip: self.skip-=1
 def handle_data(self,d):
  if not self.skip:
   s=' '.join(d.split())
   if s: self.out.append(s)
p=P(); p.feed(open(sys.argv[1],encoding='utf-8',errors='ignore').read())
for s in p.out:
 if re.search(r'Rajasthan|Kota|B\\. ?Tech|M\\. ?Tech|MBA|BBA|BCA|Ph\\. ?D|Admission|Department|University',s,re.I): print(s)
PY
